package com.vobichngan.kanzi;

/**
 * EXPERIMENTAL SHADOW-ONLY decision policy for a second, same-frame Small REC.
 *
 * Guard is necessary but not sufficient: only extreme, skewed true-vertical
 * source quads qualify for a retry. An anomalously short FIRST OCR text must
 * be present; long, plausible original text is never touched.
 *
 * Provenance precondition for a host: a candidate MUST be produced by real
 * offline OCR of the ORIGINAL FRAME pixels and its recomputed perspective crop,
 * never generated by any language model or inferred from neighboring text.
 *
 * This class performs ZERO OCR/DET inference. It is not wired into camera,
 * reading flow, TTS, white rectangles, or the production app.
 */
public final class VerticalRecRescuePolicy {
    private VerticalRecRescuePolicy() {}
    public static final int MAX_ORIGINAL_CODEPOINTS_FOR_RETRY = 3;
    public static final int MIN_NEW_CODEPOINTS_FOR_ACCEPT = 10;
    public static final float MIN_NEW_CONFIDENCE_FOR_ACCEPT = 0.80f;
    public static final int MAX_EXTRA_REC_INFERENCES_PER_FRAME = 2;

    public static boolean shouldRetry(VerticalCropAxisGuard.Inspection inspection,
                                      String original, int extraRecAlreadyPerformed) {
        if (inspection == null ||
            inspection.status != VerticalCropAxisGuard.Status.X_SORT_AXIS_RISK) return false;
        if (original == null || extraRecAlreadyPerformed < 0 ||
            extraRecAlreadyPerformed >= MAX_EXTRA_REC_INFERENCES_PER_FRAME) return false;
        return original.codePointCount(0, original.length()) <= MAX_ORIGINAL_CODEPOINTS_FOR_RETRY;
    }

    /** Return the *unaltered* original unless strong nonsemantic OCR evidence is met.
     * Does not compare linguistic meaning or invent missing characters.
     * Do not call without having obtained the candidate from the same frame.
     */
    public static Decision decide(VerticalCropAxisGuard.Inspection inspection,
                                  String original, String candidate, float candidateConfidence,
                                  int extraRecAlreadyPerformedBeforeCandidate) {
        if (!shouldRetry(inspection, original, extraRecAlreadyPerformedBeforeCandidate))
            return new Decision(original, false, "RETRY_NOT_ALLOWED");
        if (candidate == null || !Float.isFinite(candidateConfidence) ||
            candidateConfidence < MIN_NEW_CONFIDENCE_FOR_ACCEPT ||
            candidate.codePointCount(0,candidate.length()) < MIN_NEW_CODEPOINTS_FOR_ACCEPT)
            return new Decision(original, false, "CANDIDATE_INSUFFICIENT");
        return new Decision(candidate, true, "STRONG_OCR_CANDIDATE");
    }

    public static final class Decision {
        public final String selectedText;
        public final boolean accepted;
        public final String reason;
        private Decision(String s, boolean yes, String why) {
            selectedText = s; accepted = yes; reason = why;
        }
    }
}
